insert into public.learning_content
(content_id,faculty,subject,content_type,access_tier,display_order,content_data,is_published)
values
('bmlt-advanced-qms-audit-eqa-mcq-001','BMLT','BMLT NHPC Licensing','mcq','free',5000,$json${"question":"Which document defines an organization's quality policy and overall quality management system?","translation":"","options":["Quality manual","Patient register","Equipment logbook","Reagent inventory"],"correctIndex":0,"explanation":"The quality manual describes the quality management system and its scope.","explanationNe":"गुणस्तर म्यानुअलले प्रयोगशालाको गुणस्तर व्यवस्थापन प्रणाली र यसको दायरा वर्णन गर्छ।","topic":"Quality documentation"}$json$::jsonb,true),
('bmlt-advanced-qms-audit-eqa-mcq-002','BMLT','BMLT NHPC Licensing','mcq','free',5001,$json${"question":"What is the primary purpose of an internal quality audit?","translation":"","options":["To identify system conformity and improvement opportunities","To punish staff","To replace external assessment","To increase test volume"],"correctIndex":0,"explanation":"An internal audit systematically evaluates whether processes meet defined requirements.","explanationNe":"आन्तरिक अडिटले प्रक्रिया तोकिएका मापदण्डअनुसार चलेका छन् कि छैनन् जाँच गर्छ।","topic":"Internal audit"}$json$::jsonb,true),
('bmlt-advanced-qms-audit-eqa-mcq-003','BMLT','BMLT NHPC Licensing','mcq','free',5002,$json${"question":"An audit finding supported by objective evidence that a requirement is not met is called:","translation":"","options":["Nonconformity","Opportunity only","Risk acceptance","Calibration"],"correctIndex":0,"explanation":"A nonconformity is a failure to fulfil a specified requirement.","explanationNe":"तोकिएको आवश्यकता पूरा नभएको प्रमाणित अवस्था nonconformity हो।","topic":"Audit findings"}$json$::jsonb,true),
('bmlt-advanced-qms-audit-eqa-mcq-004','BMLT','BMLT NHPC Licensing','mcq','free',5003,$json${"question":"Which approach selects audit activities based on patient and process risk?","translation":"","options":["Risk-based auditing","Random punishment","Financial auditing only","Inventory counting"],"correctIndex":0,"explanation":"Risk-based auditing prioritizes high-risk processes and potential harm.","explanationNe":"जोखिममा आधारित अडिटले बिरामीलाई बढी असर गर्न सक्ने प्रक्रियालाई प्राथमिकता दिन्छ।","topic":"Risk-based audit"}$json$::jsonb,true),
('bmlt-advanced-qms-audit-eqa-mcq-005','BMLT','BMLT NHPC Licensing','mcq','free',5004,$json${"question":"A corrective action should primarily address:","translation":"","options":["The root cause of an identified nonconformity","Only the visible symptom","The person who reported it","The audit schedule"],"correctIndex":0,"explanation":"Corrective action removes the cause to prevent recurrence.","explanationNe":"Corrective action ले समस्या दोहोरिन नदिन मूल कारण हटाउँछ।","topic":"Corrective action"}$json$::jsonb,true),
('bmlt-advanced-qms-audit-eqa-mcq-006','BMLT','BMLT NHPC Licensing','mcq','free',5005,$json${"question":"Which tool is commonly used to explore possible root causes across categories?","translation":"","options":["Fishbone diagram","Pie chart","Levey-Jennings chart","Scattergram for calibration only"],"correctIndex":0,"explanation":"A fishbone diagram organizes potential causes such as people, methods, equipment and environment.","explanationNe":"Fishbone diagram ले व्यक्ति, विधि, उपकरण र वातावरणजस्ता सम्भावित कारण छुट्याउँछ।","topic":"Root cause analysis"}$json$::jsonb,true),
('bmlt-advanced-qms-audit-eqa-mcq-007','BMLT','BMLT NHPC Licensing','mcq','free',5006,$json${"question":"The '5 Whys' technique is used to:","translation":"","options":["Trace a problem toward its underlying cause","Calculate reference intervals","Verify a pipette volume","Select a blood group"],"correctIndex":0,"explanation":"Repeatedly asking why helps move beyond symptoms toward root causes.","explanationNe":"५ पटक ‘किन’ सोध्दा सतही लक्षणभन्दा मूल कारण पत्ता लगाउन मद्दत हुन्छ।","topic":"Root cause analysis"}$json$::jsonb,true),
('bmlt-advanced-qms-audit-eqa-mcq-008','BMLT','BMLT NHPC Licensing','mcq','free',5007,$json${"question":"What demonstrates that a corrective action was effective?","translation":"","options":["Follow-up evidence that the problem has not recurred","A signed attendance sheet","A verbal promise","Closing the complaint immediately"],"correctIndex":0,"explanation":"Effectiveness review checks whether the implemented action solved the problem.","explanationNe":"कार्यान्वयन गरिएको सुधारले समस्या हटायो कि हटाएन भनेर पुनः जाँच्नु effectiveness review हो।","topic":"Effectiveness review"}$json$::jsonb,true),
('bmlt-advanced-qms-audit-eqa-mcq-009','BMLT','BMLT NHPC Licensing','mcq','free',5008,$json${"question":"External quality assessment (EQA) commonly evaluates laboratory performance by:","translation":"","options":["Testing samples with externally assigned or compared results","Repeating the same control internally only","Inspecting staff uniforms","Counting patient visits"],"correctIndex":0,"explanation":"EQA compares a laboratory's results with assigned values or peer laboratories.","explanationNe":"EQA मा बाह्य रूपमा तोकिएको मान वा अन्य प्रयोगशालासँग नतिजा तुलना गरिन्छ।","topic":"EQA"}$json$::jsonb,true),
('bmlt-advanced-qms-audit-eqa-mcq-010','BMLT','BMLT NHPC Licensing','mcq','free',5009,$json${"question":"A laboratory receives a proficiency-testing sample. What should staff do?","translation":"","options":["Process it like a routine patient sample","Send it to another laboratory","Adjust the result to match a target","Use a special method not used routinely"],"correctIndex":0,"explanation":"Proficiency samples should be handled using the routine method and workflow.","explanationNe":"Proficiency sample लाई नियमित बिरामीको नमुनाजस्तै प्रक्रिया गर्नुपर्छ।","topic":"Proficiency testing"}$json$::jsonb,true),
('bmlt-advanced-qms-audit-eqa-mcq-011','BMLT','BMLT NHPC Licensing','mcq','free',5010,$json${"question":"Discussing a proficiency-testing result with another participating laboratory before submission is:","translation":"","options":["Generally prohibited because it compromises independent assessment","Required for accuracy","A form of calibration","Always acceptable"],"correctIndex":0,"explanation":"Collaboration before reporting can invalidate independent performance assessment.","explanationNe":"नतिजा बुझाउनुअघि अर्को सहभागी प्रयोगशालासँग उत्तर मिलाउनु स्वतन्त्र मूल्याङ्कनलाई बिगार्छ।","topic":"Proficiency testing ethics"}$json$::jsonb,true),
('bmlt-advanced-qms-audit-eqa-mcq-012','BMLT','BMLT NHPC Licensing','mcq','free',5011,$json${"question":"A result outside the EQA acceptance limit should first trigger:","translation":"","options":["Investigation of the testing process and possible causes","Deletion of the result","Changing the patient report","Ignoring it if internal QC passed"],"correctIndex":0,"explanation":"An unacceptable EQA result requires documented investigation and appropriate action.","explanationNe":"EQA नतिजा सीमा बाहिर भए कारण खोजी र अभिलेखसहित सुधार गर्नुपर्छ।","topic":"EQA investigation"}$json$::jsonb,true),
('bmlt-advanced-qms-audit-eqa-mcq-013','BMLT','BMLT NHPC Licensing','mcq','free',5012,$json${"question":"Which is the best example of a quality indicator in the pre-examination phase?","translation":"","options":["Percentage of specimens rejected for haemolysis","Number of staff birthdays","Laboratory electricity bill","Number of computers"],"correctIndex":0,"explanation":"Specimen rejection due to haemolysis monitors a pre-examination quality issue.","explanationNe":"Hemolysis का कारण अस्वीकृत नमुनाको प्रतिशत pre-analytical quality indicator हो।","topic":"Quality indicators"}$json$::jsonb,true),
('bmlt-advanced-qms-audit-eqa-mcq-014','BMLT','BMLT NHPC Licensing','mcq','free',5013,$json${"question":"Turnaround time (TAT) is commonly measured from:","translation":"","options":["A defined start point such as specimen receipt to result release","Staff arrival to departure","Reagent opening to expiry","Patient registration to billing only"],"correctIndex":0,"explanation":"The laboratory must define TAT start and end points consistently.","explanationNe":"TAT को सुरु र अन्त्य बिन्दु प्रयोगशालाले स्पष्ट रूपमा परिभाषित गर्नुपर्छ।","topic":"Quality indicators"}$json$::jsonb,true),
('bmlt-advanced-qms-audit-eqa-mcq-015','BMLT','BMLT NHPC Licensing','mcq','free',5014,$json${"question":"A sudden rise in specimen rejection rate should lead to:","translation":"","options":["Trend review and investigation of collection and transport processes","Immediate dismissal of the collector","Changing reference ranges","Stopping all testing indefinitely"],"correctIndex":0,"explanation":"A trend may indicate a systemic collection, labeling or transport problem.","explanationNe":"नमुना अस्वीकृति बढ्नुले collection, labeling वा transport मा प्रणालीगत समस्या देखाउन सक्छ।","topic":"Quality indicators"}$json$::jsonb,true),
('bmlt-advanced-qms-audit-eqa-mcq-016','BMLT','BMLT NHPC Licensing','mcq','free',5015,$json${"question":"Which record provides evidence that staff are competent for an assigned test?","translation":"","options":["Competency assessment record","Duty roster alone","Salary sheet","Visitor log"],"correctIndex":0,"explanation":"Competency records document training, observation and demonstrated performance.","explanationNe":"Competency अभिलेखले तालिम र काम गर्ने क्षमता प्रमाणित गर्छ।","topic":"Personnel competence"}$json$::jsonb,true),
('bmlt-advanced-qms-audit-eqa-mcq-017','BMLT','BMLT NHPC Licensing','mcq','free',5016,$json${"question":"When should competency be reassessed?","translation":"","options":["At planned intervals and after relevant changes or performance concerns","Only on the first day of employment","Never after initial training","Only when requested by patients"],"correctIndex":0,"explanation":"Periodic and event-triggered reassessment helps maintain competence.","explanationNe":"नियमित अन्तरालमा र विधि परिवर्तन वा समस्या आएपछि क्षमता पुनः मूल्याङ्कन गर्नुपर्छ।","topic":"Personnel competence"}$json$::jsonb,true),
('bmlt-advanced-qms-audit-eqa-mcq-018','BMLT','BMLT NHPC Licensing','mcq','free',5017,$json${"question":"A controlled document is revised. What should happen to the obsolete version?","translation":"","options":["Prevent unintended use and retain it only as required by policy","Leave copies at every bench","Erase the revision history","Continue using both versions"],"correctIndex":0,"explanation":"Obsolete documents must be withdrawn or clearly identified to prevent use.","explanationNe":"पुरानो कागजात अनजानेमा प्रयोग नहोस् भनेर हटाउन वा स्पष्ट रूपमा obsolete चिन्ह लगाउनुपर्छ।","topic":"Document control"}$json$::jsonb,true),
('bmlt-advanced-qms-audit-eqa-mcq-019','BMLT','BMLT NHPC Licensing','mcq','free',5018,$json${"question":"Why is document version control important?","translation":"","options":["It ensures staff use the current approved procedure","It makes documents longer","It replaces staff training","It removes the need for records"],"correctIndex":0,"explanation":"Version control prevents inconsistent work from outdated instructions.","explanationNe":"Version control ले पुरानो निर्देशनका कारण फरक-फरक काम हुने जोखिम घटाउँछ।","topic":"Document control"}$json$::jsonb,true),
('bmlt-advanced-qms-audit-eqa-mcq-020','BMLT','BMLT NHPC Licensing','mcq','free',5019,$json${"question":"A change to a laboratory method should be introduced only after:","translation":"","options":["Review, authorization, validation or verification as applicable, and staff training","An informal announcement","Deleting the old SOP without review","A patient complaint"],"correctIndex":0,"explanation":"Changes need controlled review, approval and appropriate performance checks.","explanationNe":"विधि परिवर्तन गर्नुअघि समीक्षा, स्वीकृति, आवश्यक verification/validation र तालिम चाहिन्छ।","topic":"Change management"}$json$::jsonb,true),
('bmlt-advanced-qms-audit-eqa-mcq-021','BMLT','BMLT NHPC Licensing','mcq','free',5020,$json${"question":"A risk register is used to:","translation":"","options":["Record risks, assess them and track controls or actions","Store patient test results","Record only equipment serial numbers","Replace incident reporting"],"correctIndex":0,"explanation":"A risk register supports systematic identification, rating and monitoring of risks.","explanationNe":"Risk register ले जोखिम पहिचान, मूल्याङ्कन र नियन्त्रणको अनुगमन गर्छ।","topic":"Risk management"}$json$::jsonb,true),
('bmlt-advanced-qms-audit-eqa-mcq-022','BMLT','BMLT NHPC Licensing','mcq','free',5021,$json${"question":"Which factor commonly contributes to a risk priority score?","translation":"","options":["Likelihood and severity of harm","Staff age and seniority","Reagent brand only","Room number"],"correctIndex":0,"explanation":"Risk tools commonly consider likelihood and consequence, sometimes detectability.","explanationNe":"जोखिम मूल्याङ्कनमा घटना हुने सम्भावना र असरको गम्भीरता हेरिन्छ।","topic":"Risk assessment"}$json$::jsonb,true),
('bmlt-advanced-qms-audit-eqa-mcq-023','BMLT','BMLT NHPC Licensing','mcq','free',5022,$json${"question":"A near miss is an event that:","translation":"","options":["Could have caused harm but was detected or avoided before harm occurred","Always causes permanent harm","Is not worth recording","Is the same as a routine QC result"],"correctIndex":0,"explanation":"Near-miss reporting helps prevent future incidents by identifying vulnerabilities.","explanationNe":"हानि हुन सक्ने तर समयमै रोकिएको घटना near miss हो; यसलाई पनि अभिलेख गर्नुपर्छ।","topic":"Incident management"}$json$::jsonb,true),
('bmlt-advanced-qms-audit-eqa-mcq-024','BMLT','BMLT NHPC Licensing','mcq','free',5023,$json${"question":"Why should incident reports focus on system learning rather than blame?","translation":"","options":["It encourages reporting and helps prevent recurrence","It removes accountability completely","It guarantees no errors","It avoids investigation"],"correctIndex":0,"explanation":"A just learning culture supports reporting and systemic improvement while retaining accountability.","explanationNe":"दोषारोपणभन्दा प्रणाली सुधारमा जोड दिँदा घटना रिपोर्ट गर्ने वातावरण बन्छ।","topic":"Incident management"}$json$::jsonb,true),
('bmlt-advanced-qms-audit-eqa-mcq-025','BMLT','BMLT NHPC Licensing','mcq','free',5024,$json${"question":"What is the purpose of management review?","translation":"","options":["To evaluate QMS performance and decide needed improvements and resources","To repeat every patient test","To replace internal audits","To approve individual sick leave"],"correctIndex":0,"explanation":"Management review evaluates quality objectives, audits, complaints, indicators, risks and resources.","explanationNe":"Management review ले QMS को अवस्था र सुधारका लागि आवश्यक स्रोत तथा निर्णय मूल्याङ्कन गर्छ।","topic":"Management review"}$json$::jsonb,true),
('bmlt-advanced-qms-audit-eqa-mock-001','BMLT','BMLT NHPC Licensing','mock','free',5100,$json${"question":"A laboratory's annual audit finds that staff use an outdated SOP at one bench. What is the most appropriate immediate response?","translation":"","options":["Remove or clearly withdraw the obsolete copy and provide the current approved SOP","Ignore it because other benches are correct","Rewrite results from the previous month","Suspend all staff"],"correctIndex":0,"explanation":"Control the document first, then investigate why the obsolete copy remained available.","explanationNe":"पहिले पुरानो SOP हटाएर हालको स्वीकृत SOP उपलब्ध गराउनुहोस्, त्यसपछि पुरानो प्रति किन रह्यो खोज्नुहोस्।","topic":"Document control case"}$json$::jsonb,true),
('bmlt-advanced-qms-audit-eqa-mock-002','BMLT','BMLT NHPC Licensing','mock','free',5101,$json${"question":"A corrective action was implemented after repeated mislabeled specimens, but the error continues. What does this indicate?","translation":"","options":["Effectiveness has not been demonstrated and root-cause analysis should be revisited","The action is automatically successful","The indicator should be deleted","The audit was unnecessary"],"correctIndex":0,"explanation":"Recurrence suggests the action did not adequately address the cause.","explanationNe":"समस्या दोहोरिनुले सुधारात्मक कदमले मूल कारण समाधान नगरेको संकेत गर्छ।","topic":"CAPA case"}$json$::jsonb,true),
('bmlt-advanced-qms-audit-eqa-mock-003','BMLT','BMLT NHPC Licensing','mock','free',5102,$json${"question":"During EQA, a chemistry result is unacceptable while internal QC is acceptable. What is the best next step?","translation":"","options":["Review EQA sample handling, method bias, calibration and result transcription","Assume EQA is wrong","Release no patient results for a year","Alter the EQA result"],"correctIndex":0,"explanation":"Internal QC does not exclude method-specific bias or EQA handling errors.","explanationNe":"आन्तरिक QC ठीक भए पनि method bias वा EQA sample handling को समस्या हुन सक्छ।","topic":"EQA case"}$json$::jsonb,true),
('bmlt-advanced-qms-audit-eqa-mock-004','BMLT','BMLT NHPC Licensing','mock','free',5103,$json${"question":"A staff member reports a near miss involving a wrong-patient label caught before analysis. What should the laboratory do?","translation":"","options":["Record and investigate the event and strengthen identification controls","Discard the report because no harm occurred","Punish the reporter","Change the patient's reference interval"],"correctIndex":0,"explanation":"Near misses reveal weaknesses even when harm is prevented.","explanationNe":"हानि नभए पनि near miss अभिलेख गरी patient identification प्रक्रिया सुधार्नुपर्छ।","topic":"Incident case"}$json$::jsonb,true),
('bmlt-advanced-qms-audit-eqa-mock-005','BMLT','BMLT NHPC Licensing','mock','free',5104,$json${"question":"A laboratory wants to compare its turnaround time month by month. What is essential?","translation":"","options":["Use consistent definitions, start/end points and data collection methods","Change the definition each month","Include only the fastest results","Exclude delayed samples"],"correctIndex":0,"explanation":"Comparable data require stable indicator definitions and collection methods.","explanationNe":"महिनाबीच तुलना गर्न TAT को परिभाषा र मापन विधि एउटै हुनुपर्छ।","topic":"TAT case"}$json$::jsonb,true),
('bmlt-advanced-qms-audit-eqa-mock-006','BMLT','BMLT NHPC Licensing','mock','free',5105,$json${"question":"An audit checklist is completed, but no evidence is recorded for findings. What is the main weakness?","translation":"","options":["Findings are not adequately supported by objective evidence","The checklist has too many questions","Audits cannot use checklists","The laboratory needs more analyzers"],"correctIndex":0,"explanation":"Audit conclusions should be traceable to objective evidence such as records and observations.","explanationNe":"अडिट निष्कर्षलाई अभिलेख, अवलोकन वा अन्य वस्तुगत प्रमाणले समर्थन गर्नुपर्छ।","topic":"Audit evidence"}$json$::jsonb,true),
('bmlt-advanced-qms-audit-eqa-mock-007','BMLT','BMLT NHPC Licensing','mock','free',5106,$json${"question":"A laboratory repeatedly receives clotted EDTA samples. Which quality indicator is most relevant?","translation":"","options":["Rate of clotted EDTA specimens","Percentage of staff trained in fire safety","Number of chemistry reagents","Monthly electricity use"],"correctIndex":0,"explanation":"Clotted EDTA rejection monitors collection and mixing quality.","explanationNe":"Clotted EDTA नमुनाको दरले नमुना संकलन र mixing को गुणस्तर देखाउँछ।","topic":"Pre-examination indicator"}$json$::jsonb,true),
('bmlt-advanced-qms-audit-eqa-mock-008','BMLT','BMLT NHPC Licensing','mock','free',5107,$json${"question":"A new analyzer is installed. Before patient testing, the laboratory should:","translation":"","options":["Verify performance for intended use and train authorized staff","Use it immediately without checks","Rely only on the supplier brochure","Compare one patient result and approve it"],"correctIndex":0,"explanation":"Equipment and method performance must be checked before routine use.","explanationNe":"नियमित परीक्षणअघि उपकरणको performance जाँच र कर्मचारी तालिम आवश्यक हुन्छ।","topic":"Change management"}$json$::jsonb,true),
('bmlt-advanced-qms-audit-eqa-mock-009','BMLT','BMLT NHPC Licensing','mock','free',5108,$json${"question":"A staff competency assessment shows weakness in pipetting. What is the best response?","translation":"","options":["Provide targeted training and reassess practical performance","Remove the competency record","Allow independent work without restriction","Change the test reference interval"],"correctIndex":0,"explanation":"Training should address the specific gap, followed by documented reassessment.","explanationNe":"Pipetting मा कमजोरी भए लक्षित तालिम दिएर व्यवहारिक क्षमता पुनः जाँच्नुपर्छ।","topic":"Competency case"}$json$::jsonb,true),
('bmlt-advanced-qms-audit-eqa-mock-010','BMLT','BMLT NHPC Licensing','mock','free',5109,$json${"question":"An audit identifies that temperature logs are incomplete. Which action best addresses the system?","translation":"","options":["Determine why recording fails, assign responsibility and monitor completion","Fill all missing values from memory","Stop monitoring temperature","Delete the log sheet"],"correctIndex":0,"explanation":"A sustainable action addresses workflow, responsibility and follow-up.","explanationNe":"लगातार तापक्रम अभिलेखका लागि जिम्मेवारी र प्रक्रिया स्पष्ट गरी अनुगमन गर्नुपर्छ।","topic":"Corrective action"}$json$::jsonb,true),
('bmlt-advanced-qms-audit-eqa-mock-011','BMLT','BMLT NHPC Licensing','mock','free',5110,$json${"question":"A laboratory's risk assessment rates a low-frequency event as potentially catastrophic. How should it be treated?","translation":"","options":["Prioritize control because severity is very high","Ignore it due to low likelihood","Record it only after it happens","Lower the severity score to zero"],"correctIndex":0,"explanation":"High-severity hazards may require strong controls even when likelihood is low.","explanationNe":"सम्भावना कम भए पनि असर अत्यन्त गम्भीर हुन सक्ने जोखिमलाई नियन्त्रण गर्नुपर्छ।","topic":"Risk assessment"}$json$::jsonb,true),
('bmlt-advanced-qms-audit-eqa-mock-012','BMLT','BMLT NHPC Licensing','mock','free',5111,$json${"question":"A proficiency-testing provider sends an unknown sample. The laboratory's routine procedure requires two-level QC. What should staff do?","translation":"","options":["Follow the routine procedure, including required QC","Skip QC because it is an EQA sample","Ask another participant for the expected value","Use a different unvalidated method"],"correctIndex":0,"explanation":"EQA should reflect the laboratory's normal testing process.","explanationNe":"EQA ले प्रयोगशालाको वास्तविक नियमित परीक्षण प्रक्रिया प्रतिबिम्बित गर्नुपर्छ।","topic":"Proficiency testing"}$json$::jsonb,true),
('bmlt-advanced-qms-audit-eqa-mock-013','BMLT','BMLT NHPC Licensing','mock','free',5112,$json${"question":"A complaint alleges a delayed critical result. Which records are most useful for investigation?","translation":"","options":["Specimen receipt, analysis, verification, communication and critical-result logs","Only staff leave records","Only the reagent catalogue","The laboratory building plan"],"correctIndex":0,"explanation":"A complete timeline helps locate the delay and assess communication.","explanationNe":"नमुना प्राप्तिदेखि नतिजा जानकारी गराउँदासम्मका अभिलेखले ढिलाइ कहाँ भयो देखाउँछन्।","topic":"Complaint management"}$json$::jsonb,true),
